<?php
require_once '../../config/auth.php'; require_once '../../config/database.php'; requireRole('admin');
$department=trim($_GET['jurusan']??''); $month=max(1,min(12,(int)($_GET['bulan']??date('n')))); $year=max(2020,(int)($_GET['tahun']??date('Y')));
$months=[1=>'Januari',2=>'Februari',3=>'Maret',4=>'April',5=>'Mei',6=>'Juni',7=>'Juli',8=>'Agustus',9=>'September',10=>'Oktober',11=>'November',12=>'Desember'];
$stmt=$pdo->prepare("SELECT c.id,c.nama_kelas,COUNT(DISTINCT s.id) total_siswa,COUNT(DISTINCT CASE WHEN p.status='lunas' THEN s.id END) total_lunas,COALESCE(SUM(CASE WHEN p.status='lunas' THEN p.nominal ELSE 0 END),0) total_masuk FROM classes c INNER JOIN students s ON s.kelas_id=c.id LEFT JOIN student_dues d ON d.class_id=c.id AND d.jenis_kas='kelas' AND d.bulan=? AND d.tahun=? AND d.status='aktif' LEFT JOIN student_due_payments p ON p.student_due_id=d.id AND p.student_id=s.id WHERE COALESCE(NULLIF(c.jurusan, ''), 'Belum diatur')=? GROUP BY c.id,c.nama_kelas ORDER BY c.nama_kelas"); $stmt->execute([$month,$year,$department]); $classes=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Rekap Kas'; require_once '../../includes/header.php'; require_once '../../includes/sidebar.php';
?>
<main class="main-content"><?php require_once '../../includes/navbar.php'; ?><div class="role-page"><div class="role-wrap"><div class="role-hero"><a class="role-back" href="index.php?bulan=<?= $month ?>&tahun=<?= $year ?>"><i class="bi bi-arrow-left"></i> Kas Per Jurusan</a><span class="text-uppercase small">Jurusan</span><h2><?= htmlspecialchars($department) ?></h2><p class="mb-0">Rekap kelas bulan <?= $months[$month] ?> <?= $year ?>.</p></div><div class="role-card"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>No</th><th>Kelas</th><th>Total Siswa</th><th>Sudah Bayar</th><th>Belum Bayar</th><th>Total Masuk</th><th>Aksi</th></tr></thead><tbody><?php foreach($classes as $index=>$class): $total=(int)$class['total_siswa'];$paid=(int)$class['total_lunas']; ?><tr><td><?= $index+1 ?></td><td><strong><?= htmlspecialchars($class['nama_kelas']) ?></strong></td><td><?= $total ?></td><td class="text-success fw-semibold"><?= $paid ?></td><td class="text-danger fw-semibold"><?= max(0,$total-$paid) ?></td><td>Rp <?= number_format((float)$class['total_masuk'],0,',','.') ?></td><td><a class="btn btn-sm btn-primary" href="kelas.php?id=<?= (int)$class['id'] ?>&jurusan=<?= urlencode($department) ?>&bulan=<?= $month ?>&tahun=<?= $year ?>"><i class="bi bi-people"></i> Lihat Siswa</a></td></tr><?php endforeach; ?><?php if(!$classes): ?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada kelas pada jurusan ini.</td></tr><?php endif; ?></tbody></table></div></div></div></div></main><?php require_once '../../includes/footer.php'; ?>
